const Module = require("module");
const lib = require("vt2-vuln-lib");

// TOP-LEVEL (module-scope) capability escape through a LOGICAL-OPERATOR
// value container -- the defect CLASS this fixture pins is not any
// particular Node API, and not even any particular container spelling:
// it is that the value-flow walker used to be an ENUMERATION of container
// node kinds, so anything it had not been taught about failed OPEN.
//
// VT-307c-capability-flow's walker recursed through object literals,
// array literals, conditionals, spreads, and concise-arrow bodies -- but
// not through `||`/`??`/`&&`, the direct value-selecting siblings of the
// ternary it DID handle. The final VT-307d go/no-go invariant review
// reproduced seven end-to-end violations from that one gap (real Node
// execution + a gate-eligible, complete closure + the exact installed
// package OUT + an EMPTY incompleteness array), and this task's own
// pre-implementation sweep found thirteen more.
//
// The construct below composes TWO of those value forms -- a logical-OR
// default whose fallback is an object literal holding the capability --
// precisely so that passing it requires the generic, closed-by-default
// traversal rather than a patch for either shape alone. It runs the
// moment this module is loaded, never inside any function, and the
// analyzer can never rule out that configure uses the escaped capability
// to load a different installed module, including the separate,
// never-imported top-level vt2-vuln-lib@1.9.0 instance.
function configure(loaderConfig) {
  return loaderConfig;
}
configure(process.env.VT_LOADER_OVERRIDE || { loader: Module });

function useHolder() {
  return lib.dangerousOp();
}

module.exports = { useHolder };
